        pool.sort(key=score, reverse=True)
        total_str = fmt_amount(pool[0][1])
    date_iso = None
    for raw in variant_texts:
        date_iso = extract_date(raw)
        if date_iso:
            break
    return {'date': date_iso, 'total_amount': total_str}


def main():
    files = sorted(p.name for p in IMG_DIR.iterdir()
                   if p.suffix.lower() in {'.jpg', '.jpeg', '.png', '.webp'})
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for name in files:
        res = extract_receipt_fields(IMG_DIR / name)
        row_idx = ws.max_row + 1
        ws.cell(row=row_idx, column=1, value=name)
        ws.cell(row=row_idx, column=2, value=res['date'])
        amt_cell = ws.cell(row=row_idx, column=3, value=res['total_amount'])
        if res['total_amount'] is not None:
            amt_cell.number_format = '@'
        print(name, res)
    wb.save(OUT_PATH)


if __name__ == '__main__':
    main()
